package trie

import "testing"

func TestBasicInsertSearch(t *testing.T) {
	tr := NewTrie()
	tr.Insert("apple")
	tr.Insert("app")
	if !tr.Search("apple") {
		t.Error("apple should be found")
	}
	if !tr.Search("app") {
		t.Error("app should be found")
	}
	if tr.Search("ap") {
		t.Error("ap should not be found (not inserted)")
	}
}

func TestStartsWith(t *testing.T) {
	tr := NewTrie()
	tr.Insert("hello")
	if !tr.StartsWith("hel") {
		t.Error("should start with hel")
	}
	if tr.StartsWith("world") {
		t.Error("should not start with world")
	}
	if !tr.StartsWith("") {
		t.Error("every trie starts with empty prefix")
	}
}

func TestCountWords(t *testing.T) {
	tr := NewTrie()
	tr.Insert("cat")
	tr.Insert("car")
	tr.Insert("dog")
	tr.Insert("cat")
	if tr.CountWords() != 3 {
		t.Errorf("want 3 distinct words, got %d", tr.CountWords())
	}
}

func TestEmptyTrie(t *testing.T) {
	tr := NewTrie()
	if tr.Search("a") {
		t.Error("should not find anything in empty trie")
	}
	if tr.StartsWith("a") {
		t.Error("should not find prefix in empty trie")
	}
}

func TestLongWords(t *testing.T) {
	tr := NewTrie()
	words := []string{"programming", "program", "prog", "pro"}
	for _, w := range words {
		tr.Insert(w)
	}
	for _, w := range words {
		if !tr.Search(w) {
			t.Errorf("%s should be found", w)
		}
	}
	if tr.CountWords() != 4 {
		t.Errorf("want 4 words, got %d", tr.CountWords())
	}
}

